func _run_tests() -> void:
	var stage := await instantiate_scene("res://story/character_stage.tscn")
	if not check("stage_instantiated", stage != null, "La scena character_stage.tscn deve essere istanziata senza errori"):
		return

	var elena_data = load("res://story/elena.tres")
	var marco_data = load("res://story/marco.tres")
	if not check("resources_loaded", elena_data != null and marco_data != null, "I file elena.tres e marco.tres devono essere caricabili"):
		return

	var elena_disp = call_if_exists(stage, "add_character", ["elena", elena_data, "left"])
	if not check("add_elena", elena_disp != null, "add_character deve restituire il CharacterDisplay creato per Elena"):
		return

	var pos: Vector2 = get_prop(elena_disp, "position", Vector2.ZERO)
	check("elena_pos", pos.distance_to(Vector2(100, 200)) < 1.0, "Il personaggio a sinistra deve essere posizionato a (100, 200), attualmente è a %s" % str(pos))

	var fetched_elena = call_if_exists(stage, "get_character", ["elena"])
	check("get_char", fetched_elena == elena_disp, "get_character('elena') deve restituire il display di Elena")
	check("elena_texture", get_prop(elena_disp, "texture") != null, "CharacterDisplay deve avere una texture assegnata")

	var marco_disp = call_if_exists(stage, "add_character", ["marco", marco_data, "right"])
	if not check("add_marco", marco_disp != null, "add_character deve poter aggiungere anche Marco"):
		return

	call_if_exists(stage, "focus_character", ["elena"])
	await wait_seconds(0.35)
	var elena_col: Color = get_prop(elena_disp, "modulate", Color.WHITE)
	var marco_col: Color = get_prop(marco_disp, "modulate", Color.WHITE)
	check("elena_bright", elena_col.r > 0.8, "Con focus su Elena, Elena deve avere colore pieno (modulate.r = %.2f)" % elena_col.r)
	check("marco_dimmed", marco_col.r < 0.8, "Con focus su Elena, Marco deve scurirsi (modulate.r = %.2f)" % marco_col.r)

	call_if_exists(stage, "focus_character", ["marco"])
	await wait_seconds(0.35)
	elena_col = get_prop(elena_disp, "modulate", Color.WHITE)
	marco_col = get_prop(marco_disp, "modulate", Color.WHITE)
	check("elena_dimmed", elena_col.r < 0.8, "Con focus su Marco, Elena deve scurirsi (modulate.r = %.2f)" % elena_col.r)
	check("marco_bright", marco_col.r > 0.8, "Con focus su Marco, Marco deve avere colore pieno (modulate.r = %.2f)" % marco_col.r)

	call_if_exists(stage, "remove_character", ["elena"])
	var elena_after_remove = call_if_exists(stage, "get_character", ["elena"])
	check("remove_char", elena_after_remove == null, "Dopo remove_character('elena'), get_character('elena') deve restituire null")
	await wait_seconds(0.45)
	var is_hidden: bool = (get_prop(elena_disp, "visible") == false) or (get_prop(elena_disp, "modulate", Color.WHITE).a < 0.1)
	check("elena_invisible", is_hidden, "Dopo fade_out di rimozione, Elena deve diventare invisibile o con trasparenza nulla")
